{"command":"create","path":"/tmp/summarize.py","file_text":"import json
d=json.load(open('/workspace/contracts/openapi.contract.json'))

def simplify(schema, depth=0):
    if schema is None:
        return None
    if '$ref' in schema:
        return schema['$ref'].replace('#/components/schemas/','Ref:')
    t = schema.get('type')
    if t == 'object':
        props = schema.get('properties', {})
        req = schema.get('required', [])
        out = {}
        for k,v in props.items():
            out[k+('*' if k in req else '')] = simplify(v, depth+1)
        if schema.get('additionalProperties') is True:
            out['<additionalProperties>'] = True
        return out
    if t == 'array':
        return [simplify(schema.get('items'), depth+1)]
    if 'enum' in schema:
        return {'enum': schema['enum']}
    if 'allOf' in schema:
        return [simplify(s, depth+1) for s in schema['allOf']]
    if 'oneOf' in schema:
        return {'oneOf':[simplify(s, depth+1) for s in schema['oneOf']]}
    return t

for p, methods in d['paths'].items():
    for m, op in methods.items():
        print('='*80)
        print(m.upper(), p, op.get('operationId'))
        params = op.get('parameters', [])
        if params:
            print('PARAMS:', [(x.get('name'), x.get('in'), x.get('required')) for x in params])
        rb = op.get('requestBody')
        if rb:
            schema = rb['content']['application/json']['schema']
            print('REQUEST:', json.dumps(simplify(schema)))
        for code, resp in op.get('responses', {}).items():
            content = resp.get('content')
            if content:
                schema = content['application/json']['schema']
                print(f'RESP {code}:', json.dumps(simplify(schema)))
