{"command":"create","path":"/workspace/backend/internal/db/db.go","file_text":"package db

import (
	"context"
	"os"

	"github.com/jackc/pgx/v5/pgxpool"
)

var Pool *pgxpool.Pool

func Connect(ctx context.Context) error {
	url := os.Getenv("DATABASE_URL")
	pool, err := pgxpool.New(ctx, url)
	if err != nil {
		return err
	}
	Pool = pool
	return nil
}

func Ping(ctx context.Context) error {
	if Pool == nil {
		return context.DeadlineExceeded
	}
	return Pool.Ping(ctx)
}
"}

{"command":"create","path":"/workspace/backend/internal/api/util.go","file_text":"package api

import (
	"context"
	"encoding/json"
	"net/http"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

type Server struct {
	DB *pgxpool.Pool
}

type errBody struct {
	Error string `json:"error"`
	Code  string `json:"code"`
}

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeData(w http.ResponseWriter, status int, data interface{}) {
	writeJSON(w, status, map[string]interface{}{"data": data})
}

func writeErr(w http.ResponseWriter, status int, code, msg string) {
	if msg == "" {
		msg = code
	}
	writeJSON(w, status, errBody{Error: msg, Code: code})
}

func readJSON(r *http.Request, v interface{}) bool {
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(v); err != nil {
		return false
	}
	return true
}

func parseTime(s string) (time.Time, bool) {
	if s == "" {
		return time.Time{}, false
	}
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return time.Time{}, false
	}
	return t, true
}

func nowISO() string {
	return time.Now().UTC().Format(time.RFC3339)
}

func isoOrNil(t *time.Time) interface{} {
	if t == nil {
		return nil
	}
	return t.UTC().Format(time.RFC3339)
}

func isoOf(t time.Time) string {
	return t.UTC().Format(time.RFC3339)
}

// noRows helper
func isNoRows(err error) bool {
	return err == pgx.ErrNoRows
}

type ctxKey string

const (
	ctxUserID ctxKey = "userID"
	ctxRoles  ctxKey = "roles"
	ctxActiveRole ctxKey = "activeRole"
	ctxUsername ctxKey = "username"
)

func withAuth(ctx context.Context, userID string, roles []string, activeRole string, username string) context.Context {
	ctx = context.WithValue(ctx, ctxUserID, userID)
	ctx = context.WithValue(ctx, ctxRoles, roles)
	ctx = context.WithValue(ctx, ctxActiveRole, activeRole)
	ctx = context.WithValue(ctx, ctxUsername, username)
	return ctx
}

func userIDFrom(ctx context.Context) string {
	v, _ := ctx.Value(ctxUserID).(string)
	return v
}
func rolesFrom(ctx context.Context) []string {
	v, _ := ctx.Value(ctxRoles).([]string)
	return v
}
func activeRoleFrom(ctx context.Context) string {
	v, _ := ctx.Value(ctxActiveRole).(string)
	return v
}
func usernameFrom(ctx context.Context) string {
	v, _ := ctx.Value(ctxUsername).(string)
	return v
}

func hasRole(ctx context.Context, role string) bool {
	for _, r := range rolesFrom(ctx) {
		if r == role {
			return true
		}
	}
	return false
}
"}

{"command":"create","path":"/workspace/backend/internal/api/auth.go","file_text":"package api

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"net/http"
	"strings"

	"golang.org/x/crypto/bcrypt"
)

func hashPassword(pw string) (string, error) {
	b, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
	return string(b), err
}

func checkPassword(hash, pw string) bool {
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(pw)) == nil
}

func newToken() string {
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

// authMiddleware extracts bearer [REDACTED], loads session+user, sets context.
func (s *Server) authMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		authz := r.Header.Get("Authorization")
		token := ""
		if strings.HasPrefix(authz, "Bearer ") {
			token = strings.TrimPrefix(authz, "Bearer ")
		}
		if token == "" {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "missing bearer [REDACTED]")
			return
		}
		ctx := r.Context()
		var userID, activeRole, username string
		var active bool
		err := s.DB.QueryRow(ctx, `SELECT sessions.user_id, coalesce(sessions.active_role,''), users.username, users.active
			FROM sessions JOIN users ON users.id = sessions.user_id WHERE sessions.token=$1`, token).
			Scan(&userID, &activeRole, &username, &active)
		if err != nil || !active {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "invalid session")
			return
		}
		rows, err := s.DB.Query(ctx, `SELECT role FROM user_roles WHERE user_id=$1`, userID)
		if err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", "")
			return
		}
		var roles []string
		for rows.Next() {
			var role string
			_ = rows.Scan(&role)
			roles = append(roles, role)
		}
		rows.Close()
		ctx = withAuth(ctx, userID, roles, activeRole, username)
		next(w, r.WithContext(ctx))
	}
}

// requireRoleSelected ensures activeRole is set among the roles required for handlers that need one.
func requireRoleSelected(ctx context.Context) bool {
	return activeRoleFrom(ctx) != ""
}
"}

{"command":"create","path":"/workspace/backend/internal/api/audit.go","file_text":"package api

import (
	"context"
	"encoding/json"
)

func (s *Server) audit(ctx context.Context, actorID, role, action, entityType, entityID string, success bool, details map[string]interface{}) {
	if details == nil {
		details = map[string]interface{}{}
	}
	b, _ := json.Marshal(details)
	_, _ = s.DB.Exec(ctx, `INSERT INTO audit_log (actor_id, role, action, entity_type, entity_id, success, details)
		VALUES ($1,$2,$3,$4,$5,$6,$7)`, nilIfEmpty(actorID), role, action, entityType, entityID, success, b)
}

func nilIfEmpty(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

func (s *Server) emitEvent(ctx context.Context, evtType, entityType, entityID string, audienceRole string, audienceUser string, payload map[string]interface{}) {
	b, _ := json.Marshal(payload)
	_, _ = s.DB.Exec(ctx, `INSERT INTO events (type, entity_type, entity_id, audience_role, audience_user_id, payload)
		VALUES ($1,$2,$3,$4,$5,$6)`, evtType, entityType, entityID, nilIfEmpty(audienceRole), nilIfEmptyUUID(audienceUser), b)
}

func nilIfEmptyUUID(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}
"}

{"command":"create","path":"/workspace/backend/internal/api/handlers_auth.go","file_text":"package api

import (
	"net/http"

	"github.com/google/uuid"
)

type authenticateReq struct {
	Username string `json:"username"`
	Password string `json:"password"`
}

func (s *Server) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
	var req authenticateReq
	if !readJSON(r, &req) || req.Username == "" || req.Password == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	ctx := r.Context()
	var userID, passHash string
	var active bool
	err := s.DB.QueryRow(ctx, `SELECT id, password_hash, active FROM users WHERE username=$1`, req.Username).Scan(&userID, &passHash, &active)
	if err != nil || !active || !checkPassword(passHash, req.Password) {
		s.audit(ctx, "", "", "sign_in", "user", req.Username, false, nil)
		writeErr(w, http.StatusUnauthorized, "invalid_credentials", "invalid username or password")
		return
	}
	roles := s.loadRoles(ctx, userID)
	activeRole := ""
	if len(roles) == 1 {
		activeRole = roles[0]
	}
	token := newToken()
	_, err = s.DB.Exec(ctx, `INSERT INTO sessions (token, user_id, active_role) VALUES ($1,$2,$3)`, token, userID, nilIfEmpty(activeRole))
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	s.audit(ctx, userID, activeRole, "sign_in", "user", userID, true, nil)
	writeData(w, http.StatusOK, map[string]interface{}{
		"sessionToken": token,
		"userId":       userID,
		"roles":        roles,
		"activeRole":   activeRole,
	})
}

func (s *Server) loadRoles(ctx interface{ Deadline() }, userID string) []string {
	return nil
}

type selectRoleReq struct {
	Role string `json:"role"`
}

func (s *Server) SelectActiveRole(w http.ResponseWriter, r *http.Request) {
	var req selectRoleReq
	if !readJSON(r, &req) || req.Role == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	ctx := r.Context()
	userID := userIDFrom(ctx)
	roles := rolesFrom(ctx)
	found := false
	for _, rr := range roles {
		if rr == req.Role {
			found = true
		}
	}
	if !found {
		writeErr(w, http.StatusForbidden, "role_not_held", "user does not hold this role")
		return
	}
	authz := r.Header.Get("Authorization")
	token := authz[len("Bearer "):]
	_, err := s.DB.Exec(ctx, `UPDATE sessions SET active_role=$1 WHERE token=$2`, req.Role, token)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	s.audit(ctx, userID, req.Role, "select_active_role", "user", userID, true, map[string]interface{}{"role": req.Role})
	writeData(w, http.StatusOK, map[string]interface{}{"activeRole": req.Role, "roles": roles})
}

type createUserReq struct {
	Username         string   `json:"username"`
	InitialPassword  string   `json:"initialPassword"`
	Email            string   `json:"email"`
	FullName         string   `json:"fullName"`
	Phone            string   `json:"phone"`
	Roles            []string `json:"roles"`
	Qualifications   []string `json:"qualifications"`
	Certifications   []certReq `json:"certifications"`
	Active           *bool    `json:"active"`
	AssignedLocationID string `json:"assignedLocationId"`
}

type certReq struct {
	Code      string  `json:"code"`
	Active    bool    `json:"active"`
	ExpiresAt string  `json:"expiresAt"`
}

func (s *Server) CreateUser(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	if activeRoleFrom(ctx) != "administrator" {
		writeErr(w, http.StatusForbidden, "forbidden", "administrator role required")
		return
	}
	var req createUserReq
	if !readJSON(r, &req) || req.Username == "" || req.InitialPassword == "" || len(req.Roles) == 0 {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	for _, rl := range req.Roles {
		if !isValidRoleStr(rl) {
			writeErr(w, http.StatusBadRequest, "invalid_user", "invalid role")
			return
		}
	}
	active := true
	if req.Active != nil {
		active = *req.Active
	}
	var existing string
	err := s.DB.QueryRow(ctx, `SELECT id FROM users WHERE username=$1`, req.Username).Scan(&existing)
	if err == nil {
		writeErr(w, http.StatusConflict, "username_exists", "")
		return
	}
	hash, _ := hashPassword(req.InitialPassword)
	userID := uuid.NewString()
	var locID interface{}
	if req.AssignedLocationID != "" {
		locID = req.AssignedLocationID
	}
	_, err = s.DB.Exec(ctx, `INSERT INTO users (id, username, password_hash, email, full_name, phone, active, assigned_location_id)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`, userID, req.Username, hash, nilIfEmpty(req.Email), nilIfEmpty(req.FullName), nilIfEmpty(req.Phone), active, locID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	for _, rl := range req.Roles {
		_, _ = s.DB.Exec(ctx, `INSERT INTO user_roles (user_id, role) VALUES ($1,$2) ON CONFLICT DO NOTHING`, userID, rl)
	}
	for _, q := range req.Qualifications {
		_, _ = s.DB.Exec(ctx, `INSERT INTO user_qualifications (user_id, qualification) VALUES ($1,$2) ON CONFLICT DO NOTHING`, userID, q)
	}
	for _, c := range req.Certifications {
		var exp interface{}
		if t, ok := parseTime(c.ExpiresAt); ok {
			exp = t
		}
		_, _ = s.DB.Exec(ctx, `INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`, userID, c.Code, c.Active, exp)
	}
	actorID := userIDFrom(ctx)
	s.audit(ctx, actorID, "administrator", "create_user", "user", userID, true, map[string]interface{}{"username": req.Username, "roles": req.Roles})
	writeData(w, http.StatusCreated, map[string]interface{}{
		"userId": userID, "username": req.Username, "email": req.Email, "fullName": req.FullName, "phone": req.Phone,
		"roles": req.Roles, "qualifications": req.Qualifications, "certifications": req.Certifications, "active": active,
	})
}

type updateUserAccessReq struct {
	UserID             string    `json:"userId"`
	Roles              []string  `json:"roles"`
	Qualifications     []string  `json:"qualifications"`
	Certifications     []certReq `json:"certifications"`
	Active             *bool     `json:"active"`
	AssignedLocationID string    `json:"assignedLocationId"`
}

func (s *Server) UpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	if activeRoleFrom(ctx) != "administrator" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req updateUserAccessReq
	if !readJSON(r, &req) || req.UserID == "" || len(req.Roles) == 0 || req.Active == nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	var exists string
	err := s.DB.QueryRow(ctx, `SELECT id FROM users WHERE id=$1`, req.UserID).Scan(&exists)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	var locID interface{}
	if req.AssignedLocationID != "" {
		locID = req.AssignedLocationID
	}
	_, err = s.DB.Exec(ctx, `UPDATE users SET active=$1, assigned_location_id=$2, updated_at=now() WHERE id=$3`, *req.Active, locID, req.UserID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	_, _ = s.DB.Exec(ctx, `DELETE FROM user_roles WHERE user_id=$1`, req.UserID)
	for _, rl := range req.Roles {
		_, _ = s.DB.Exec(ctx, `INSERT INTO user_roles (user_id, role) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.UserID, rl)
	}
	_, _ = s.DB.Exec(ctx, `DELETE FROM user_qualifications WHERE user_id=$1`, req.UserID)
	for _, q := range req.Qualifications {
		_, _ = s.DB.Exec(ctx, `INSERT INTO user_qualifications (user_id, qualification) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.UserID, q)
	}
	_, _ = s.DB.Exec(ctx, `DELETE FROM user_certifications WHERE user_id=$1`, req.UserID)
	for _, c := range req.Certifications {
		var exp interface{}
		if t, ok := parseTime(c.ExpiresAt); ok {
			exp = t
		}
		_, _ = s.DB.Exec(ctx, `INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`, req.UserID, c.Code, c.Active, exp)
	}
	actorID := userIDFrom(ctx)
	s.audit(ctx, actorID, "administrator", "update_user_access", "user", req.UserID, true, map[string]interface{}{"roles": req.Roles})
	writeData(w, http.StatusCreated, map[string]interface{}{
		"userId": req.UserID, "roles": req.Roles, "qualifications": req.Qualifications, "certifications": req.Certifications, "active": *req.Active,
	})
}

func isValidRoleStr(r string) bool {
	switch r {
	case "administrator", "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team":
		return true
	}
	return false
}

func (s *Server) ReadUser(w http.ResponseWriter, r *http.Request, userID string) {
	ctx := r.Context()
	actorRole := activeRoleFrom(ctx)
	actorID := userIDFrom(ctx)
	if actorRole != "administrator" && actorRole != "dispatcher" && actorID != userID {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var username, email, fullName, phone string
	var active bool
	err := s.DB.QueryRow(ctx, `SELECT username, coalesce(email,''), coalesce(full_name,''), coalesce(phone,''), active FROM users WHERE id=$1`, userID).
		Scan(&username, &email, &fullName, &phone, &active)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	roles := s.fetchRoles(ctx, userID)
	quals := s.fetchQualifications(ctx, userID)
	certs := s.fetchCertifications(ctx, userID)
	writeData(w, http.StatusOK, map[string]interface{}{
		"userId": userID, "username": username, "email": email, "fullName": fullName, "phone": phone,
		"roles": roles, "qualifications": quals, "certifications": certs, "active": active,
	})
}

func (s *Server) fetchRoles(ctx interface{}, userID string) []string {
	rows, err := s.DB.Query(ctx.(interface{}).(contextType), `SELECT role FROM user_roles WHERE user_id=$1`, userID)
	_ = err
	var out []string
	if rows != nil {
		for rows.Next() {
			var r string
			_ = rows.Scan(&r)
			out = append(out, r)
		}
		rows.Close()
	}
	return out
}
"}

