{"command":"create","path":"/workspace/backend/internal/api/serviceability.go","file_text":"package api

import (
	"context"
	"encoding/json"
	"math"
	"sync"
)

var svcMu sync.Mutex
var svcVersion int
var svcComputing bool

func (s *Server) bumpNetworkRevision(ctx context.Context) {
	go s.recomputeServiceability(context.Background())
}

// recomputeServiceability computes a new complete serviceability snapshot and publishes it,
// while any concurrent readers continue to see the previous complete version until this
// one is fully written.
func (s *Server) recomputeServiceability(ctx context.Context) {
	svcMu.Lock()
	if svcComputing {
		svcMu.Unlock()
		return
	}
	svcComputing = true
	svcMu.Unlock()
	defer func() {
		svcMu.Lock()
		svcComputing = false
		svcMu.Unlock()
	}()

	rows, err := s.DB.Query(ctx, `SELECT id, name, latitude, longitude, coverage_km FROM locations WHERE active=true AND is_collection_point=true`)
	if err != nil {
		return
	}
	type region struct {
		LocationID string  `json:"locationId"`
		Name       string  `json:"name"`
		Latitude   float64 `json:"latitude"`
		Longitude  float64 `json:"longitude"`
		CoverageKm float64 `json:"coverageKm"`
	}
	var regions []region
	for rows.Next() {
		var reg region
		_ = rows.Scan(&reg.LocationID, &reg.Name, &reg.Latitude, &reg.Longitude, &reg.CoverageKm)
		regions = append(regions, reg)
	}
	rows.Close()
	if regions == nil {
		regions = []region{}
	}
	b, _ := json.Marshal(regions)

	var nextVersion int
	_ = s.DB.QueryRow(ctx, `SELECT coalesce(max(version),0)+1 FROM serviceability_snapshots`).Scan(&nextVersion)
	_, err = s.DB.Exec(ctx, `INSERT INTO serviceability_snapshots (version, status, network_revision, regions, active_collection_point_count)
		VALUES ($1,'complete',$1,$2,$3)`, nextVersion, b, len(regions))
	if err != nil {
		return
	}
	svcMu.Lock()
	svcVersion = nextVersion
	svcMu.Unlock()
}

func haversineKm(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0
	toRad := func(deg float64) float64 { return deg * math.Pi / 180 }
	dLat := toRad(lat2 - lat1)
	dLon := toRad(lon2 - lon1)
	a := math.Sin(dLat/2)*math.Sin(dLat/2) + math.Cos(toRad(lat1))*math.Cos(toRad(lat2))*math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

type latestSnapshot struct {
	Version                    int
	Status                     string
	ComputedAt                 string
	NetworkRevision            int
	Regions                    []map[string]interface{}
	ActiveCollectionPointCount int
}

func (s *Server) getLatestServiceabilitySnapshot(ctx context.Context) latestSnapshot {
	var out latestSnapshot
	var regionsB []byte
	var computedAt interface{}
	err := s.DB.QueryRow(ctx, `SELECT version, status, computed_at, network_revision, regions, active_collection_point_count
		FROM serviceability_snapshots ORDER BY version DESC LIMIT 1`).
		Scan(&out.Version, &out.Status, &computedAt, &out.NetworkRevision, &regionsB, &out.ActiveCollectionPointCount)
	if err != nil {
		// no snapshot yet; compute synchronously once
		s.recomputeServiceability(ctx)
		err = s.DB.QueryRow(ctx, `SELECT version, status, computed_at, network_revision, regions, active_collection_point_count
			FROM serviceability_snapshots ORDER BY version DESC LIMIT 1`).
			Scan(&out.Version, &out.Status, &computedAt, &out.NetworkRevision, &regionsB, &out.ActiveCollectionPointCount)
		if err != nil {
			return out
		}
	}
	var regions []map[string]interface{}
	_ = json.Unmarshal(regionsB, &regions)
	out.Regions = regions
	if t, ok := computedAt.(interface{ String() string }); ok {
		out.ComputedAt = t.String()
	}
	return out
}

type serviceabilityCheckInput struct {
	OriginLat, OriginLng float64
	SampleTypeID         string
	RequestedAt          interface{}
	DeliveryDeadline     interface{}
}

type serviceabilityResult struct {
	Serviceable         bool
	Reason              string
	TargetLaboratoryID  string
	EstimatedArrivalISO string
	Version             int
}

// evaluateServiceability performs the structural network check for a given origin/sample type/deadline.
func (s *Server) evaluateServiceability(ctx context.Context, lat, lng float64, sampleTypeID string, deliveryDeadlineISO string) serviceabilityResult {
	snap := s.getLatestServiceabilitySnapshot(ctx)
	res := serviceabilityResult{Version: snap.Version}

	// 1. within coverage of an active collection point
	inCoverage := false
	for _, reg := range snap.Regions {
		rlat, _ := reg["latitude"].(float64)
		rlng, _ := reg["longitude"].(float64)
		rcov, _ := reg["coverageKm"].(float64)
		if haversineKm(lat, lng, rlat, rlng) <= rcov {
			inCoverage = true
			break
		}
	}
	if !inCoverage {
		res.Reason = "outside_service_coverage"
		return res
	}

	// 2. find an active laboratory that accepts the sample type
	rows, err := s.DB.Query(ctx, `SELECT l.id, l.latitude, l.longitude FROM locations l
		JOIN laboratory_acceptance a ON a.laboratory_id=l.id AND a.sample_type_id=$1 AND a.accepts=true
		WHERE l.active=true AND l.is_laboratory=true`, sampleTypeID)
	type lab struct {
		ID       string
		Lat, Lng float64
	}
	var labs []lab
	if err == nil {
		for rows.Next() {
			var l lab
			_ = rows.Scan(&l.ID, &l.Lat, &l.Lng)
			labs = append(labs, l)
		}
		rows.Close()
	}
	if len(labs) == 0 {
		res.Reason = "no_accepting_laboratory"
		return res
	}

	// 3. pick nearest lab as target (route existence approximated by distance-based travel time)
	best := labs[0]
	bestDist := haversineKm(lat, lng, best.Lat, best.Lng)
	for _, l := range labs[1:] {
		d := haversineKm(lat, lng, l.Lat, l.Lng)
		if d < bestDist {
			best = l
			bestDist = d
		}
	}
	res.TargetLaboratoryID = best.ID

	// naive travel time estimate: 2 min per km + 30 min handling
	travelMinutes := bestDist*2 + 30
	deadline, ok := parseTime(deliveryDeadlineISO)
	if !ok {
		res.Reason = "no_route"
		return res
	}
	arrival := timeNow().Add(minutesToDuration(travelMinutes))
	if arrival.After(deadline) {
		res.Reason = "deadline_unreachable"
		res.EstimatedArrivalISO = isoOf(arrival)
		return res
	}

	// 4. capacity check at laboratory (regular units available)
	var availUnits int
	_ = s.DB.QueryRow(ctx, `SELECT capacity_units - reserved_units FROM locations WHERE id=$1`, best.ID).Scan(&availUnits)
	if availUnits <= 0 {
		res.Reason = "insufficient_capacity"
		return res
	}

	res.Serviceable = true
	res.Reason = "serviceable"
	res.EstimatedArrivalISO = isoOf(arrival)
	return res
}
"}

