type sampleTypeReq struct {
	Name                       string   `json:"name"`
	QualifiedCollectorRequired *bool    `json:"qualifiedCollectorRequired"`
	RequiredQualification      string   `json:"requiredQualification"`
	ContainerType              string   `json:"containerType"`
	TemperatureMinC            *float64 `json:"temperatureMinC"`
	TemperatureMaxC            *float64 `json:"temperatureMaxC"`
	IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
	RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
	BatchingAllowed            *bool    `json:"batchingAllowed"`
}

func (s *Server) CreateSampleType(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role != "administrator" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req sampleTypeReq
	if !readJSON(r, &req) || req.Name == "" || req.ContainerType == "" || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if *req.TemperatureMinC > *req.TemperatureMaxC {
		writeErr(w, http.StatusBadRequest, "invalid_handling_rule", "")
		return
	}
	qcr := false
	if req.QualifiedCollectorRequired != nil {
		qcr = *req.QualifiedCollectorRequired
	}
	cooled := false
	if req.RequiresCooledRoute != nil {
		cooled = *req.RequiresCooledRoute
	}
	batching := true
	if req.BatchingAllowed != nil {
		batching = *req.BatchingAllowed
	}
	id := uuid.NewString()
	_, err := s.DB.Exec(ctx, `INSERT INTO sample_types (id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`, id, req.Name, qcr, nilIfEmpty(req.RequiredQualification), req.ContainerType, *req.TemperatureMinC, *req.TemperatureMaxC, cooled, batching)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	for _, inc := range req.IncompatibleSampleTypes {
		_, _ = s.DB.Exec(ctx, `INSERT INTO sample_type_incompatibilities (sample_type_id, incompatible_sample_type_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, id, inc)
	}
	s.audit(ctx, userIDFrom(ctx), role, "create_sample_type", "sample_type", id, true, map[string]interface{}{"name": req.Name})
	writeData(w, http.StatusCreated, map[string]interface{}{
		"sampleTypeId": id, "name": req.Name, "qualifiedCollectorRequired": qcr, "requiredQualification": req.RequiredQualification,
		"containerType": req.ContainerType, "temperatureMinC": *req.TemperatureMinC, "temperatureMaxC": *req.TemperatureMaxC,
		"incompatibleSampleTypes": req.IncompatibleSampleTypes, "requiresCooledRoute": cooled, "batchingAllowed": batching,
	})
}

func (s *Server) UpdateSampleType(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role != "administrator" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req struct {
		SampleTypeID               string   `json:"sampleTypeId"`
		QualifiedCollectorRequired *bool    `json:"qualifiedCollectorRequired"`
		RequiredQualification      string   `json:"requiredQualification"`
		ContainerType              string   `json:"containerType"`
		TemperatureMinC            *float64 `json:"temperatureMinC"`
		TemperatureMaxC            *float64 `json:"temperatureMaxC"`
		IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
		RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
		BatchingAllowed            *bool    `json:"batchingAllowed"`
	}
	if !readJSON(r, &req) || req.SampleTypeID == "" || req.ContainerType == "" || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	var name string
	err := s.DB.QueryRow(ctx, `SELECT name FROM sample_types WHERE id=$1`, req.SampleTypeID).Scan(&name)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	qcr := false
	if req.QualifiedCollectorRequired != nil {
		qcr = *req.QualifiedCollectorRequired
	}
	cooled := false
	if req.RequiresCooledRoute != nil {
		cooled = *req.RequiresCooledRoute
	}
	batching := true
	if req.BatchingAllowed != nil {
		batching = *req.BatchingAllowed
	}
	_, err = s.DB.Exec(ctx, `UPDATE sample_types SET qualified_collector_required=$1, required_qualification=$2, container_type=$3,
		temperature_min_c=$4, temperature_max_c=$5, requires_cooled_route=$6, batching_allowed=$7, updated_at=now() WHERE id=$8`,
		qcr, nilIfEmpty(req.RequiredQualification), req.ContainerType, *req.TemperatureMinC, *req.TemperatureMaxC, cooled, batching, req.SampleTypeID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	_, _ = s.DB.Exec(ctx, `DELETE FROM sample_type_incompatibilities WHERE sample_type_id=$1`, req.SampleTypeID)
	for _, inc := range req.IncompatibleSampleTypes {
		_, _ = s.DB.Exec(ctx, `INSERT INTO sample_type_incompatibilities (sample_type_id, incompatible_sample_type_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.SampleTypeID, inc)
	}
	s.audit(ctx, userIDFrom(ctx), role, "update_sample_type", "sample_type", req.SampleTypeID, true, nil)
	writeData(w, http.StatusCreated, map[string]interface{}{
		"sampleTypeId": req.SampleTypeID, "name": name, "qualifiedCollectorRequired": qcr, "requiredQualification": req.RequiredQualification,
		"containerType": req.ContainerType, "temperatureMinC": *req.TemperatureMinC, "temperatureMaxC": *req.TemperatureMaxC,
		"incompatibleSampleTypes": req.IncompatibleSampleTypes, "requiresCooledRoute": cooled, "batchingAllowed": batching,
	})
}

func (s *Server) ConfigureLaboratoryAcceptance(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role != "administrator" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req struct {
		LaboratoryID string `json:"laboratoryId"`
		SampleTypeID string `json:"sampleTypeId"`
		Accepts      *bool  `json:"accepts"`
	}
	if !readJSON(r, &req) || req.LaboratoryID == "" || req.SampleTypeID == "" || req.Accepts == nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	_, err := s.DB.Exec(ctx, `INSERT INTO laboratory_acceptance (laboratory_id, sample_type_id, accepts) VALUES ($1,$2,$3)
		ON CONFLICT (laboratory_id, sample_type_id) DO UPDATE SET accepts=$3`, req.LaboratoryID, req.SampleTypeID, *req.Accepts)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_acceptance", "")
		return
	}
	s.bumpNetworkRevision(ctx)
	id := req.LaboratoryID + ":" + req.SampleTypeID
	s.audit(ctx, userIDFrom(ctx), role, "configure_laboratory_acceptance", "laboratory", req.LaboratoryID, true, map[string]interface{}{"sampleTypeId": req.SampleTypeID, "accepts": *req.Accepts})
	writeData(w, http.StatusOK, map[string]interface{}{"acceptanceId": id, "accepts": *req.Accepts})
}

func (s *Server) ConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role != "administrator" && role != "node_handler" && role != "laboratory_team" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       *int   `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	if !readJSON(r, &req) || req.ResourceID == "" || req.CapacityUnits == nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if *req.CapacityUnits < 0 {
		writeErr(w, http.StatusBadRequest, "invalid_capacity", "")
		return
	}
	cooled := 0
	if req.CooledCapacityUnits != nil {
		cooled = *req.CooledCapacityUnits
	}
	// Non-admin roles may only configure capacity at their assigned location.
	if role == "node_handler" || role == "laboratory_team" {
		var assignedID *string
		_ = s.DB.QueryRow(ctx, `SELECT assigned_location_id::text FROM users WHERE id=$1`, userIDFrom(ctx)).Scan(&assignedID)
		if assignedID == nil || *assignedID != req.ResourceID {
			writeErr(w, http.StatusForbidden, "forbidden", "")
			return
		}
	}
	// try location first, then connection
	tag, err := s.DB.Exec(ctx, `UPDATE locations SET capacity_units=$1, cooled_capacity_units=$2, updated_at=now() WHERE id=$3 AND reserved_units<=$1 AND cooled_reserved_units<=$2`, *req.CapacityUnits, cooled, req.ResourceID)
	if err == nil && tag.RowsAffected() > 0 {
		s.audit(ctx, userIDFrom(ctx), role, "configure_capacity", "location", req.ResourceID, true, nil)
		writeData(w, http.StatusOK, map[string]interface{}{"resourceId": req.ResourceID, "capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled})
		return
	}
	var locExists bool
	_ = s.DB.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM locations WHERE id=$1)`, req.ResourceID).Scan(&locExists)
	if locExists {
		writeErr(w, http.StatusConflict, "capacity_reserved", "")
		return
	}
	tag2, err2 := s.DB.Exec(ctx, `UPDATE connections SET capacity_units=$1, cooled_capacity_units=$2, updated_at=now() WHERE id=$3 AND reserved_units<=$1 AND cooled_reserved_units<=$2`, *req.CapacityUnits, cooled, req.ResourceID)
	if err2 == nil && tag2.RowsAffected() > 0 {
		s.audit(ctx, userIDFrom(ctx), role, "configure_capacity", "connection", req.ResourceID, true, nil)
		writeData(w, http.StatusOK, map[string]interface{}{"resourceId": req.ResourceID, "capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled})
		return
	}
	var connExists bool
	_ = s.DB.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM connections WHERE id=$1)`, req.ResourceID).Scan(&connExists)
	if connExists {
		writeErr(w, http.StatusConflict, "capacity_reserved", "")
		return
	}
	writeErr(w, http.StatusNotFound, "not_found", "")
}
"}

