{"command":"create","path":"/workspace/backend/internal/api/idempotency.go","file_text":"package api

import (
	"context"
	"encoding/json"
	"net/http"
)

// checkIdempotency returns (found, statusCode, body) for a previously stored response.
func (s *Server) checkIdempotency(ctx context.Context, key, operation string) (bool, int, map[string]interface{}) {
	if key == "" {
		return false, 0, nil
	}
	var respB []byte
	var status int
	err := s.DB.QueryRow(ctx, `SELECT response, status_code FROM idempotency_keys WHERE key=$1 AND operation=$2`, key, operation).Scan(&respB, &status)
	if err != nil {
		return false, 0, nil
	}
	var body map[string]interface{}
	_ = json.Unmarshal(respB, &body)
	return true, status, body
}

func (s *Server) storeIdempotency(ctx context.Context, key, operation string, status int, body interface{}) {
	if key == "" {
		return
	}
	b, _ := json.Marshal(body)
	_, _ = s.DB.Exec(ctx, `INSERT INTO idempotency_keys (key, operation, response, status_code) VALUES ($1,$2,$3,$4)
		ON CONFLICT (key) DO NOTHING`, key, operation, b, status)
}

// writeIdempotentData writes a successful data response and records it under the idempotency key.
func (s *Server) writeIdempotentData(w http.ResponseWriter, ctx context.Context, key, operation string, status int, data interface{}) {
	body := map[string]interface{}{"data": data}
	s.storeIdempotency(ctx, key, operation, status, body)
	writeJSON(w, status, body)
}

// replayIfPresent checks for an existing idempotent response and writes it if found. Returns true if replayed.
func (s *Server) replayIfPresent(w http.ResponseWriter, ctx context.Context, key, operation string) bool {
	found, status, body := s.checkIdempotency(ctx, key, operation)
	if !found {
		return false
	}
	writeJSON(w, status, body)
	return true
}
"}

