	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "initiate_handoff", http.StatusCreated, map[string]interface{}{
		"handoffId": handoffID, "senderId": userID, "receiverId": req.ReceiverID, "currentHolderId": holderID, "status": "pending",
	})
}

type confirmHandoffReq struct {
	HandoffID        string `json:"handoffId"`
	ConfirmationSide string `json:"confirmationSide"`
	ConfirmedAt      string `json:"confirmedAt"`
	IdempotencyKey   string `json:"idempotencyKey"`
}

func (s *Server) ConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	var req confirmHandoffReq
	if !readJSON(r, &req) || req.HandoffID == "" || req.ConfirmedAt == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
		writeErr(w, http.StatusBadRequest, "invalid_confirmation_side", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	confirmedAt, ok := parseTime(req.ConfirmedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "confirm_handoff") {
		return
	}
	userID := userIDFrom(ctx)

	var sampleID, senderID, receiverID, status string
	var senderConfirmed, receiverConfirmed bool
	err := s.DB.QueryRow(ctx, `SELECT sample_id, sender_id, receiver_id, status, sender_confirmed, receiver_confirmed FROM handoffs WHERE id=$1`, req.HandoffID).
		Scan(&sampleID, &senderID, &receiverID, &status, &senderConfirmed, &receiverConfirmed)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if status != "pending" {
		writeErr(w, http.StatusConflict, "handoff_inactive", "")
		return
	}
	if req.ConfirmationSide == "sender" && userID != senderID {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	if req.ConfirmationSide == "receiver" && userID != receiverID {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	if req.ConfirmationSide == "sender" {
		senderConfirmed = true
	} else {
		receiverConfirmed = true
	}
	newStatus := "pending"
	holderID := senderID
	if senderConfirmed && receiverConfirmed {
		newStatus = "confirmed"
		holderID = receiverID
	}
	_, err = s.DB.Exec(ctx, `UPDATE handoffs SET sender_confirmed=$1, receiver_confirmed=$2, status=$3, confirmed_at=$4 WHERE id=$5`,
		senderConfirmed, receiverConfirmed, newStatus, confirmedIfDone(newStatus, confirmedAt), req.HandoffID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	if newStatus == "confirmed" {
		_, _ = s.DB.Exec(ctx, `UPDATE samples SET current_holder_id=$1, updated_at=now() WHERE id=$2`, holderID, sampleID)
	}
	s.audit(ctx, userID, role, "confirm_handoff", "handoff", req.HandoffID, true, map[string]interface{}{"side": req.ConfirmationSide, "status": newStatus})
	if newStatus == "confirmed" {
		s.emitEvent(ctx, "handoff_confirmed", "handoff", req.HandoffID, "", "", map[string]interface{}{"sampleId": sampleID, "handoffId": req.HandoffID})
	}
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "confirm_handoff", http.StatusCreated, map[string]interface{}{
		"handoffId": req.HandoffID, "status": newStatus, "senderConfirmed": senderConfirmed, "receiverConfirmed": receiverConfirmed, "currentHolderId": holderID,
	})
}

func confirmedIfDone(status string, t interface{ }) interface{} {
	if status == "confirmed" {
		return t
	}
	return nil
}

type labReceiptReq struct {
	SampleID       string `json:"sampleId"`
	LaboratoryID   string `json:"laboratoryId"`
	ReceivedAt     string `json:"receivedAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (s *Server) ConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	if role != "laboratory_team" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req labReceiptReq
	if !readJSON(r, &req) || req.SampleID == "" || req.LaboratoryID == "" || req.ReceivedAt == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	receivedAt, ok := parseTime(req.ReceivedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "confirm_laboratory_receipt") {
		return
	}
	userID := userIDFrom(ctx)

	var assignedLoc *string
	_ = s.DB.QueryRow(ctx, `SELECT assigned_location_id::text FROM users WHERE id=$1`, userID).Scan(&assignedLoc)
	if assignedLoc == nil || *assignedLoc != req.LaboratoryID {
		writeErr(w, http.StatusForbidden, "wrong_laboratory_operator", "")
		return
	}
	var holderID, sampleStatus, targetLab string
	var deadline interface{}
	err := s.DB.QueryRow(ctx, `SELECT coalesce(current_holder_id::text,''), status, coalesce(target_laboratory_id::text,''), delivery_deadline
		FROM samples s JOIN requests r ON r.id=s.request_id WHERE s.id=$1`, req.SampleID).
		Scan(&holderID, &sampleStatus, &targetLab, &deadline)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if holderID != userID {
		writeErr(w, http.StatusConflict, "custody_conflict", "")
		return
	}
	var pendingCount int
	_ = s.DB.QueryRow(ctx, `SELECT count(*) FROM handoffs WHERE sample_id=$1 AND status='pending'`, req.SampleID).Scan(&pendingCount)
	if pendingCount > 0 {
		writeErr(w, http.StatusConflict, "pending_handoff_exists", "")
		return
	}
