const staleThreshold = 10 * time.Minute

// staleFromRaw reports whether a recorded-at value (typically a *time.Time or time.Time
// scanned from the database) is older than the staleness threshold, or unknown (nil).
func staleFromRaw(v interface{}) bool {
	switch t := v.(type) {
	case time.Time:
		return time.Since(t) > staleThreshold
	case *time.Time:
		if t == nil {
			return true
		}
		return time.Since(*t) > staleThreshold
	default:
		return true
	}
}"}

