{"command":"create","path":"/workspace/frontend/src/App.tsx","file_text":"import React from "react";
import { BrowserRouter, Routes, Route, Navigate, Link, useNavigate } from "react-router-dom";
import { useSession } from "./lib/session";
import LoginPage from "./pages/LoginPage";
import DashboardPage from "./pages/DashboardPage";
import RequestPage from "./pages/RequestPage";
import ServiceabilityPage from "./pages/ServiceabilityPage";
import WorkPage from "./pages/WorkPage";
import SampleDetailPage from "./pages/SampleDetailPage";
import MonitorPage from "./pages/MonitorPage";
import AuditPage from "./pages/AuditPage";
import CapacityPage from "./pages/CapacityPage";
import MapPage from "./pages/MapPage";
import AdminPage from "./pages/AdminPage";
import RoleSwitcher from "./pages/RoleSwitcher";

function RequireAuth({ children }: { children: React.ReactNode }) {
  const { user, loading } = useSession();
  if (loading) return <p>Loading…</p>;
  if (!user) return <Navigate to="/login" replace />;
  return <>{children}</>;
}

function Header() {
  const { user, logout } = useSession();
  const navigate = useNavigate();
  if (!user) return null;
  const onSignOut = () => {
    logout();
    navigate("/login");
  };
  return (
    <header>
      <div>
        <strong>Lab Sample Pickup &amp; Delivery</strong>
        <nav style={{ marginTop: "0.5rem" }}>
          <Link to="/dashboard">Dashboard</Link>
          <Link to="/work">My Work</Link>
          <Link to="/serviceability">Serviceability</Link>
          <Link to="/requests/new">New Request</Link>
          <Link to="/capacity">Capacity</Link>
          <Link to="/monitor">Monitor</Link>
          <Link to="/audit">Audit</Link>
          <Link to="/map">Map</Link>
          <Link to="/admin">Admin</Link>
        </nav>
      </div>
      <div>
        <span aria-label="current-role" style={{ marginRight: "1rem" }}>
          Signed in as {user.username} — role: <strong>{user.activeRole}</strong>
        </span>
        <RoleSwitcher />
        <button onClick={onSignOut} aria-label="sign-out">Sign out</button>
      </div>
    </header>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <Header />
      <main>
        <Routes>
          <Route path="/login" element={<LoginPage />} />
          <Route path="/dashboard" element={<RequireAuth><DashboardPage /></RequireAuth>} />
          <Route path="/requests/new" element={<RequireAuth><RequestPage /></RequireAuth>} />
          <Route path="/serviceability" element={<RequireAuth><ServiceabilityPage /></RequireAuth>} />
          <Route path="/work" element={<RequireAuth><WorkPage /></RequireAuth>} />
          <Route path="/samples/:sampleId" element={<RequireAuth><SampleDetailPage /></RequireAuth>} />
          <Route path="/monitor" element={<RequireAuth><MonitorPage /></RequireAuth>} />
          <Route path="/audit" element={<RequireAuth><AuditPage /></RequireAuth>} />
          <Route path="/capacity" element={<RequireAuth><CapacityPage /></RequireAuth>} />
          <Route path="/map" element={<RequireAuth><MapPage /></RequireAuth>} />
          <Route path="/admin" element={<RequireAuth><AdminPage /></RequireAuth>} />
          <Route path="*" element={<Navigate to="/dashboard" replace />} />
        </Routes>
      </main>
    </BrowserRouter>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/pages/LoginPage.tsx","file_text":"import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useSession } from "../lib/session";
import { ApiRequestError } from "../lib/api";

export default function LoginPage() {
  const { login, user } = useSession();
  const navigate = useNavigate();
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  if (user) {
    navigate("/dashboard");
  }

  const onSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSubmitting(true);
    try {
      await login(username, password);
      navigate("/dashboard");
    } catch (err) {
      if (err instanceof ApiRequestError) {
        setError("Invalid username or password.");
      } else {
        setError("Sign in failed. Please try again.");
      }
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <main>
      <div className="card" style={{ maxWidth: 420, margin: "3rem auto" }}>
        <h1>Sign in</h1>
        <form onSubmit={onSubmit}>
          <label htmlFor="username">Username</label>
          <input
            id="username"
            name="username"
            autoComplete="username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
          />
          <label htmlFor="password">Password</label>
          <input
            id="password"
            name="password"
            type="password"
            autoComplete="current-password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
          {error && <p className="error-text" role="alert">{error}</p>}
          <button type="submit" disabled={submitting}>
            {submitting ? "Signing in…" : "Sign in"}
          </button>
        </form>
