          <input
            id="containerType"
            value={containerType}
            onChange={(e) => setContainerType(e.target.value)}
            required
          />
          <label htmlFor="temperatureMinC">Min temperature (°C)</label>
          <input
            id="temperatureMinC"
            value={temperatureMinC}
            onChange={(e) => setTemperatureMinC(e.target.value)}
            required
          />
          <label htmlFor="temperatureMaxC">Max temperature (°C)</label>
