    user?.activeRole === "administrator" ||
    user?.activeRole === "node_handler" ||
    user?.activeRole === "laboratory_team";

  useEffect(() => {
    api
      .readOperationsState()
      .then(setState)
      .catch((e) => setError(e instanceof ApiRequestError ? e.message : "Failed to load"));
  }, []);

  const onSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);
    try {
      await api.configureCapacity({
        resourceId,
        capacityUnits: parseInt(capacityUnits, 10),
        cooledCapacityUnits: cooledCapacityUnits ? parseInt(cooledCapacityUnits, 10) : undefined,
      });
      setMessage("Capacity updated.");
    } catch (err) {
      setMessage(err instanceof ApiRequestError ? err.message : "Failed to update capacity");
    }
  };

  return (
    <div>
      <h1>Capacity</h1>
      {error && <p className="error-text" role="alert">{error}</p>}
      <div className="card" aria-label="capacity-list">
        <h2>Nodes &amp; laboratories</h2>
        <table>
          <thead>
            <tr>
              <th>Location</th>
              <th>Regular (avail/configured)</th>
              <th>Cooled (avail/configured)</th>
            </tr>
          </thead>
          <tbody>
            {(state?.locations ?? []).map((loc: any) => (
              <tr key={loc.id}>
                <td>{loc.name}</td>
                <td>
                  {loc.capacity?.availableUnits ?? "-"}/{loc.capacity?.capacityUnits ?? "-"}
                </td>
                <td>
                  {loc.capacity?.cooledAvailableUnits ?? "-"}/{loc.capacity?.cooledCapacityUnits ?? "-"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {canConfigure && (
        <div className="card">
          <h2>Configure capacity</h2>
          <form onSubmit={onSubmit}>
            <label htmlFor="resourceId">Resource ID</label>
            <input id="resourceId" value={resourceId} onChange={(e) => setResourceId(e.target.value)} required />
            <label htmlFor="capacityUnits">Regular capacity units</label>
            <input
              id="capacityUnits"
              value={capacityUnits}
              onChange={(e) => setCapacityUnits(e.target.value)}
              required
            />
            <label htmlFor="cooledCapacityUnits">Cooled capacity units</label>
            <input
              id="cooledCapacityUnits"
              value={cooledCapacityUnits}
              onChange={(e) => setCooledCapacityUnits(e.target.value)}
            />
            <button type="submit">Save</button>
          </form>
          {message && <p>{message}</p>}
        </div>
      )}
    </div>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/pages/MapPage.tsx","file_text":"import React, { useEffect, useRef, useState } from "react";
import maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import { Protocol } from "pmtiles";
import { api, ApiRequestError } from "../lib/api";

export default function MapPage() {
  const mapContainer = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const protocol = new Protocol();
    maplibregl.addProtocol("pmtiles", protocol.tile);

    if (!mapContainer.current) return;
    const map = new maplibregl.Map({
      container: mapContainer.current,
      style: "/map-assets/style.json",
      center: [77.5946, 12.9716],
      zoom: 11,
    });
    mapRef.current = map;

    map.on("load", async () => {
      try {
        const state = await api.readOperationsState();
        const locationFeatures = (state.locations ?? []).map((loc: any) => ({
          type: "Feature",
          geometry: {
            type: "Point",
            coordinates: [loc.coordinate.longitude, loc.coordinate.latitude],
          },
          properties: { name: loc.name, active: loc.active },
        }));
        map.addSource("network-locations", {
          type: "geojson",
          data: { type: "FeatureCollection", features: locationFeatures },
        });
        map.addLayer({
          id: "network-locations-layer",
          type: "circle",
          source: "network-locations",
          paint: {
            "circle-radius": 6,
            "circle-color": ["case", ["get", "active"], "#1a7a1a", "#999"],
          },
        });

        const workerFeatures = (state.workers ?? [])
          .filter((w: any) => w.latestLocation)
          .map((w: any) => ({
            type: "Feature",
            geometry: {
              type: "Point",
              coordinates: [w.latestLocation.longitude, w.latestLocation.latitude],
            },
            properties: { name: w.fullName, stale: w.locationStale },
          }));
        map.addSource("workers", {
          type: "geojson",
          data: { type: "FeatureCollection", features: workerFeatures },
        });
        map.addLayer({
          id: "workers-layer",
          type: "circle",
          source: "workers",
          paint: {
            "circle-radius": 5,
            "circle-color": ["case", ["get", "stale"], "#b00020", "#1c2b3a"],
          },
        });
      } catch (e) {
        setError(e instanceof ApiRequestError ? e.message : "Failed to load map overlay data");
      }
    });

    return () => {
      map.remove();
      maplibregl.removeProtocol("pmtiles");
    };
  }, []);

  return (
    <div>
      <h1>Live map</h1>
      {error && <p className="error-text" role="alert">{error}</p>}
      <div id="map-container" ref={mapContainer} aria-label="live-map" />
    </div>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/pages/AdminPage.tsx","file_text":"import React, { useState } from "react";
import { useSession } from "../lib/session";
import { api, ApiRequestError } from "../lib/api";

export default function AdminPage() {
  const { user } = useSession();
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [username, setUsername] = useState("");
  const [initialPassword, setInitialPassword] = useState("");
  const [roles, setRoles] = useState("requester");

  const [locName, setLocName] = useState("");
  const [locLat, setLocLat] = useState("");
  const [locLng, setLocLng] = useState("");
  const [locCoverageKm, setLocCoverageKm] = useState("5");

  if (user?.activeRole !== "administrator" && user?.activeRole !== "dispatcher") {
    return <p>Only administrators and dispatchers can access this page.</p>;
  }

  const createUser = async (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);
    setError(null);
    try {
      await api.createUser({
        username,
        initialPassword,
        roles: roles.split(",").map((r) => r.trim()).filter(Boolean),
        active: true,
      });
      setMessage("User created.");
    } catch (err) {
      setError(err instanceof ApiRequestError ? err.message : "Failed to create user");
    }
  };

  const createLocation = async (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);
    setError(null);
    try {
      await api.createLocation({
        name: locName,
        coordinate: { latitude: parseFloat(locLat), longitude: parseFloat(locLng) },
        coverageKm: parseFloat(locCoverageKm),
        handlingMinutes: 10,
        active: true,
        functions: { collection_point: true, transfer_point: false, hub: false, laboratory: false },
      });
      setMessage("Location created.");
    } catch (err) {
      setError(err instanceof ApiRequestError ? err.message : "Failed to create location");
    }
  };

  return (
    <div>
      <h1>Administration</h1>
      {error && <p className="error-text" role="alert">{error}</p>}
      {message && <p>{message}</p>}

      <div className="card">
        <h2>Create user</h2>
        <form onSubmit={createUser}>
          <label htmlFor="adminUsername">Username</label>
          <input id="adminUsername" value={username} onChange={(e) => setUsername(e.target.value)} required />
          <label htmlFor="adminPassword">Initial password</label>
          <input
            id="adminPassword"
            type="password"
            value={initialPassword}
            onChange={(e) => setInitialPassword(e.target.value)}
            required
          />
          <label htmlFor="adminRoles">Roles (comma separated)</label>
          <input id="adminRoles" value={roles} onChange={(e) => setRoles(e.target.value)} required />
          <button type="submit">Create user</button>
        </form>
      </div>

      <div className="card">
        <h2>Create location</h2>
        <form onSubmit={createLocation}>
          <label htmlFor="locName">Name</label>
          <input id="locName" value={locName} onChange={(e) => setLocName(e.target.value)} required />
          <label htmlFor="locLat">Latitude</label>
          <input id="locLat" value={locLat} onChange={(e) => setLocLat(e.target.value)} required />
          <label htmlFor="locLng">Longitude</label>
          <input id="locLng" value={locLng} onChange={(e) => setLocLng(e.target.value)} required />
          <label htmlFor="locCoverageKm">Coverage km</label>
          <input id="locCoverageKm" value={locCoverageKm} onChange={(e) => setLocCoverageKm(e.target.value)} />
          <button type="submit">Create location</button>
        </form>
      </div>
    </div>
  );
}
"}

